/**
 * diagnostic-memory.ts — 诊断记忆索引
 *
 * B7: 对标 Hermes MEMORY.md 冻结快照 + Claw-Code JSONL 持久化 + 严格有界。
 *
 * Hermes 模式：
 *   - 快照在会话开始时拍摄，注入系统提示，会话中间不刷新
 *   - 严格字符上限（memory 2200, user 1375）
 *   - § 分隔条目
 *
 * Claw-Code 模式：
 *   - JSONL 追加写，不重写全文件
 *   - 每条消息一行，读取快
 *
 * Synova 适配：
 *   - 诊断记忆 = 组织级索引，不是会话级
 *   - 每条记忆 ≤ 500 字符（对标 Hermes memory_char_limit 的 1/4）
 *   - 组织级上限 50 条（对标 Hermes 严格有界）
 *   - 快照在诊断开始时拍，中途不刷新
 *   - JSONL 追加写 + SQLite 索引双持久化
 */
export interface DiagnosticMemoryEntry {
    id: string;
    orgId: string;
    /** 记忆类型 */
    type: 'finding' | 'pattern' | 'lesson' | 'preference' | 'correction';
    /** 记忆内容（≤ 500 字符） */
    content: string;
    /** 来源诊断 ID */
    sourceDiagnosisId: string;
    /** 关联维度 */
    dimensions: string[];
    /** 置信度 */
    confidence: number;
    /** 使用次数（被后续诊断引用） */
    useCount: number;
    /** 创建时间 */
    createdAt: string;
    /** 最后引用时间 */
    lastReferencedAt: string;
    /** 优先级（高优先级记忆注入系统提示） */
    priority: 'high' | 'medium' | 'low';
}
export interface MemorySnapshot {
    orgId: string;
    /** 快照生成时间 */
    snapshotAt: string;
    /** 高优先级记忆（注入系统提示） */
    highPriorityEntries: DiagnosticMemoryEntry[];
    /** 总计条目数 */
    totalEntries: number;
    /** 快照是否有效 */
    valid: boolean;
}
export interface MemoryStoreConfig {
    /** 组织级记忆上限（对标 Hermes memory_char_limit） */
    maxEntriesPerOrg: number;
    /** 每条记忆最大字符数 */
    maxCharsPerEntry: number;
    /** 高优先级记忆上限（注入系统提示的） */
    maxHighPriority: number;
    /** 数据目录 */
    dataDir: string;
}
export declare function initMemoryStore(cfg: Partial<MemoryStoreConfig>): void;
/** 添加记忆。超过上限时淘汰最低优先级的旧记忆。 */
export declare function addMemory(entry: Omit<DiagnosticMemoryEntry, 'id' | 'useCount' | 'createdAt' | 'lastReferencedAt'>): DiagnosticMemoryEntry;
/** 引用记忆（增加 useCount） */
export declare function referenceMemory(memoryId: string): void;
/** 搜索记忆（模糊匹配） */
export declare function searchMemory(orgId: string, query: string, limit?: number): DiagnosticMemoryEntry[];
/** 删除记忆 */
export declare function removeMemory(memoryId: string): boolean;
/**
 * 构建组织级的冻结快照。
 * 对标 Hermes: 会话开始时拍摄，注入系统提示，中途不刷新。
 * 对标 Claw-Code: 压缩后的摘要 = 快照。
 */
export declare function buildSnapshot(orgId: string): MemorySnapshot;
/**
 * 获取冻结快照。
 * 对标 Hermes load_from_disk() 快照——诊断开始时调用一次，后续不刷新。
 */
export declare function getSnapshot(orgId: string): MemorySnapshot;
/**
 * 将快照注入系统提示。
 * 对标 Hermes 的 memory_store.system_prompt_snapshot。
 */
export declare function renderSnapshotForSystemPrompt(orgId: string, maxChars?: number): string;
/** 获取组织记忆统计 */
export declare function getMemoryStats(orgId: string): {
    total: number;
    byType: Record<string, number>;
    oldestEntry: string;
    newestEntry: string;
};
/** 清空（测试用） */
export declare function clearMemoryStore(): void;
